#include "trisolv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/* Array initialization translated to Halide, with a cache‑friendly schedule. */
static
void init_array(int n,
                Halide::Buffer<num_t, 2> L,  // logical L[i][j] stored as L(j, i)
                Halide::Buffer<num_t, 1> x,
                Halide::Buffer<num_t, 1> b,
                const Target &target) {
    Var i("i"), j("j");

    Func init_x("init_x"), init_b("init_b"), init_L("init_L");

    // x[i] = -999;
    init_x(i) = cast<num_t>(Expr(-999));

    // b[i] = i;
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n for j <= i; 0 elsewhere (unused in kernel).
    // Remember: L is stored as L(j, i) so j is the fast-varying (x) dimension.
    Expr n_expr = cast<num_t>(Expr(n));
    Expr two    = cast<num_t>(Expr(2));

    init_L(j, i) = select(j <= i,
                          (cast<num_t>(i + n - j + 1) * two) / n_expr,
                          cast<num_t>(Expr(0)));

    // ------------------------------------------------------------
    // Scheduling for initialization
    //
    // We make L’s j-dimension (dim 0) the innermost and vectorized,
    // and parallelize across rows i. This keeps accesses to L(j,i)
    // contiguous and uses multiple cores during initialization.
    // ------------------------------------------------------------
    const int vec = target.natural_vector_size(type_of<num_t>());

    // 1D initializations: just vectorize across i.
    init_x.compute_root()
          .vectorize(i, vec);
    init_b.compute_root()
          .vectorize(i, vec);

    // 2D initialization of L: parallel over rows (i), vectorize over columns (j)
    Var jo("jo"), ji("ji");
    init_L.compute_root()
          // Tile in j to keep vectorized loads/stores nicely aligned.
          .split(j, jo, ji, 64)
          .parallel(i)
          .vectorize(ji, vec);

    // Realize using the chosen target so the schedule is honored.
    init_x.realize(x, target);
    init_b.realize(b, target);
    init_L.realize(L, target);
}

int main(int argc, char *argv[]) {
    // Select a host target once and reuse it everywhere (init + kernel).
    Target target = get_host_target();

    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one.
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // initialize data (Halide pipeline with an optimized schedule)
    init_array(n, L, x, b, target);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation:
    //
    // For a fixed i:
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // We express the j-loop as a reduction over RDom, and drive the
    // i-loop from the host, updating x one element at a time.
    //
    // Because x[i] depends on x[0..i-1], we *must* keep the i-loop
    // on the host (loop-carried dependency); we cannot legally encode
    // the full triangular solve as a single pure Halide pipeline.
    // -----------------------------------------------------------------

    Func xi("xi");       // accumulates b[i] - sum_{j<i} L[i][j]*x[j]
    Func xi_div("xi_div"); // final x[i] = xi / L[i][i]

    // RDom over j = 0 .. i_param-1
    RDom r(0, i_param, "r");

    // Start from b[i]
    xi() = b_param(i_param);
    // Subtract contributions L[i][j] * x[j]
    // Recall: L[i][j] is stored as L_param(j, i_param)
    xi() -= L_param(r, i_param) * x_param(r);

    // Divide by the diagonal entry L[i][i] (L_param(i, i))
    xi_div() = xi() / L_param(i_param, i_param);

    // Bind ImageParams to our Buffers (done once, before timing).
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // JIT-compile the pipeline once for the chosen target.
    xi_div.compile_jit(target);

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Set current row index
        i_param.set(i);

        // Realize scalar xi_div() for this i.
        // We keep the simple scalar-realize pattern (one Halide
        // reduction per row), but rely on the pre-JITed pipeline.
        Halide::Buffer<num_t> xi_buf = xi_div.realize(target);

        // Update x[i] on the host
        x(i) = xi_buf();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Print results (similar style to example/gemm.cpp)
    // -----------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
